const state = $input.first().json.body;
if (state.status !== 'approved') throw new Error(`release-on-approval got a non-approved state for job ${state.jobId}: status=${state.status}`);
const payload = { jobId: state.jobId, mode: 'manual', status: 'running', currentStep: 'youtube-uploader', niche: 'news-europe' };
return [{ json: { jobId: state.jobId, updateJobB64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];

const GH_API = 'https://api.github.com/repos/' + $env.GITHUB_REPO;
const HEADERS = { Authorization: 'Bearer ' + $env.GITHUB_TOKEN, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' };
const jobId = $('Job Context').first().json.jobId;
const dispatchedAt = Date.now();

await this.helpers.httpRequest({
  method: 'POST',
  url: GH_API + '/actions/workflows/08-upload-youtube.yml/dispatches',
  headers: HEADERS,
  body: { ref: 'master', inputs: { jobId } },
  json: true,
});

const maxWaitMs = 20 * 60 * 1000;
const pollIntervalMs = 15000;
let run = null;
while (Date.now() - dispatchedAt < maxWaitMs) {
  await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
  let body;
  try {
    body = await this.helpers.httpRequest({
      method: 'GET',
      url: GH_API + '/actions/workflows/08-upload-youtube.yml/runs?event=workflow_dispatch&per_page=5',
      headers: HEADERS,
      json: true,
    });
  } catch (e) { continue; }
  const candidates = (body.workflow_runs || [])
    .filter((r) => new Date(r.created_at).getTime() >= dispatchedAt - 5000)
    .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
  if (candidates.length > 0) {
    run = candidates[0];
    if (run.status === 'completed') break;
  }
}

const succeeded = !!run && run.status === 'completed' && run.conclusion === 'success';
if (!succeeded) {
  const status = run ? run.status : 'not found';
  const conclusion = run ? run.conclusion : null;
  const htmlUrl = run ? run.html_url : '(no run found before timeout)';
  throw new Error('GitHub Actions run for "youtube-uploader" did not succeed (status: ' + status + ', conclusion: ' + conclusion + '). See ' + htmlUrl);
}
return [{ json: { succeeded: true, runId: run.id, htmlUrl: run.html_url } }];

const jobId = $('Build: youtube-uploader').first().json.jobId;
const payload = { jobId, mode: 'manual', status: 'completed', currentStep: 'youtube-uploader', niche: 'news-europe' };
return [{ json: { updateJobB64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];
